import { execFile } from 'node:child_process';
import { copyFile, mkdir, mkdtemp, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

import { unstable_readConfig } from 'wrangler';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const source = join(root, 'apps/sync');
const target = join(root, 'templates/cloudflare');
const temporary = await mkdtemp(join(tmpdir(), 'bplaylist-cloudflare-'));
const run = promisify(execFile);

try {
  // 一键部署仅复制目标目录，预先打包共享依赖以保持模板独立。
  await run(
    process.execPath,
    [
      join(source, 'node_modules/wrangler/bin/wrangler.js'),
      'deploy',
      '--dry-run',
      '--minify',
      '--outdir',
      temporary,
    ],
    { cwd: source, env: { ...process.env, CI: 'true' }, timeout: 60000 },
  );

  await mkdir(join(target, 'migrations'), { recursive: true });
  const bundle = await readFile(join(temporary, 'index.js'), 'utf8');
  await writeFile(
    join(target, 'worker.js'),
    `// Generated by vp run build:cloudflare-template.\n${bundle.replace(/^\/\/# sourceMappingURL=.*$/gm, '').trim()}\n`,
  );

  for (const filename of (await readdir(join(source, 'migrations'))).sort()) {
    if (filename.endsWith('.sql')) {
      await copyFile(join(source, 'migrations', filename), join(target, 'migrations', filename));
    }
  }

  const wrangler = JSON.parse(
    await readFile(join(source, 'node_modules/wrangler/package.json'), 'utf8'),
  ) as { version: string };

  const original = unstable_readConfig({ config: join(source, 'wrangler.jsonc') });

  const configuration = {
    $schema: 'node_modules/wrangler/config-schema.json',
    name: original.name,
    main: 'worker.js',
    compatibility_date: original.compatibility_date,
    compatibility_flags: original.compatibility_flags,
    d1_databases: original.d1_databases.map(
      (database: { binding: string; database_name?: string }) => ({
        binding: database.binding,
        database_name: database.database_name,
        database_id: '00000000-0000-0000-0000-000000000000',
        migrations_dir: 'migrations',
      }),
    ),
  };

  const manifest = {
    name: 'bplaylist-sync',
    version: '0.1.0',
    private: true,
    type: 'module',
    description: 'BPlaylist 云端同步服务',
    scripts: { deploy: 'wrangler d1 migrations apply DB --remote && wrangler deploy' },
    devDependencies: { wrangler: wrangler.version },
    engines: { node: '>=22.18.0' },
    cloudflare: {
      bindings: {
        DB: { description: '保存播放列表、播放进度和同步记录的个人数据库。' },
        SYNC_TOKEN: {
          description:
            '自行设置至少 32 位随机令牌；连接 BPlaylist 时填写相同令牌。不要使用示例值。',
        },
      },
    },
  };

  await writeFile(join(target, 'wrangler.jsonc'), `${JSON.stringify(configuration, null, 2)}\n`);
  await writeFile(join(target, 'package.json'), `${JSON.stringify(manifest, null, 2)}\n`);
  await writeFile(join(target, '.env.example'), 'SYNC_TOKEN=\n');
  await run('vp', ['fmt', join(target, 'package.json'), join(target, 'wrangler.jsonc')], {
    cwd: root,
  });
  process.stdout.write(
    'Cloudflare deployment template generated from apps/sync and shared sources.\n',
  );
} finally {
  await rm(temporary, { recursive: true, force: true });
}
